from fractions import Fraction
from math import floor

# Milliseconds per unit.
_UNIT_MS = {
    "w": 7 * 24 * 60 * 60 * 1000,
    "d": 24 * 60 * 60 * 1000,
    "h": 60 * 60 * 1000,
    "m": 60 * 1000,
    "s": 1000,
    "ms": 1,
}

# Strictly descending order: weeks, days, hours, minutes, seconds, milliseconds.
_ORDER = ["w", "d", "h", "m", "s", "ms"]
_ORDER_IDX = {u: i for i, u in enumerate(_ORDER)}


def parse_duration(text):
    """Return the duration described by `text` in whole milliseconds. See TASK.md."""
    if not isinstance(text, str):
        raise TypeError("expected a str")

    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    # Optional single leading minus; a leading plus is invalid.
    neg = False
    if s[0] == "-":
        neg = True
        s = s[1:]
        if not s:
            raise ValueError("empty duration")
    elif s[0] == "+":
        raise ValueError("leading '+' is invalid")

    components = []  # list of (unit, value_ms_fraction, has_fraction)
    i = 0
    n = len(s)
    while i < n:
        # Integer part of the number: one or more digits.
        int_start = i
        while i < n and s[i].isdigit():
            i += 1
        int_digits = s[int_start:i]
        if not int_digits:
            raise ValueError("expected a number")

        # Optional fraction, only valid for the last component (checked later).
        frac_digits = None
        if i < n and s[i] == ".":
            i += 1
            frac_start = i
            while i < n and s[i].isdigit():
                i += 1
            frac_digits = s[frac_start:i]
            if not frac_digits:
                raise ValueError("fraction needs digits after the point")

        # Unit, written directly after the number.
        if i + 2 <= n and s[i:i + 2] == "ms":
            unit = "ms"
            i += 2
        elif i < n and s[i] in "wdhms":
            unit = s[i]
            i += 1
        else:
            raise ValueError("expected a unit")

        # Build the exact millisecond value for this component.
        value = Fraction(int(int_digits))
        if frac_digits is not None:
            value += Fraction(int(frac_digits), 10 ** len(frac_digits))
        value *= _UNIT_MS[unit]

        components.append((unit, value, frac_digits is not None))

        # Separator between components: nothing, or exactly one space.
        if i < n:
            if s[i] == " ":
                i += 1
                if i >= n:
                    raise ValueError("trailing separator")
            elif s[i].isdigit():
                pass  # no separator; next component starts immediately
            else:
                raise ValueError("bad separator")

    if not components:
        raise ValueError("no components")

    # Strictly descending unit order, no duplicates.
    last = -1
    for unit, _, _ in components:
        idx = _ORDER_IDX[unit]
        if idx <= last:
            raise ValueError("units out of order or repeated")
        last = idx

    # Only the last component may carry a fraction.
    for unit, _, has_frac in components[:-1]:
        if has_frac:
            raise ValueError("fraction only allowed on the last component")

    total = Fraction(0)
    for unit, value, _ in components:
        total += value
    if neg:
        total = -total

    # Round to the nearest millisecond; exact halves round away from zero.
    if total >= 0:
        result = floor(total + Fraction(1, 2))
    else:
        result = -floor(-total + Fraction(1, 2))
    return int(result)
